{
  "title": "The Mirror and the Map",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara studies the ruined city from a hilltop.",
      "visual_description": "Mara stands on a rubble-strewn hill, unrolling a stained parchment map as the sun sets behind the broken spires of the royal city.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The Glass Diver swims out of a shattered window.",
      "visual_description": "A clear diving helmet emerges from a cracked stained-glass window, the coat reflecting scattered lamplight as the rescuer steps into the street.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "The Oracle Lamp flickers a warning.",
      "visual_description": "On a stone pedestal, an oil lamp with a single glowing eye in its flame casts shifting shadows across a cobblestone alley.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "Mara and the Glass Diver meet at the rusted castle gate.",
      "visual_description": "The two rescuers stand before a massive iron gate covered in rust and old royal banners, the lock mechanism frozen.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The Tin Fox scampers ahead to scout.",
      "visual_description": "A small metal fox with a key-wind tail and blue glass eyes darts between broken paving stones, sniffing at a cracked cornerstone.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The group encounters the Sleeping Tax Collector.",
      "visual_description": "Slumped against a ledger-book pillow, an official sleeps with stamped papers stuck to his sleeves, oblivious to the patrols nearby.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 7,
      "caption": "The Oracle Lamp warns of a cursed tower.",
      "visual_description": "The lamp's eye glows red as it casts a beam toward a twisted black tower whose windows pulse with internal light.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "Mara consults her map in a crumbling courtyard.",
      "visual_description": "Mara kneels on fallen stones, tracing a route past a fountain choked with weeds while the tin fox watches from a broken bench.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The Glass Diver peers through a magic door.",
      "visual_description": "A door of polished obsidian shows no handle; the diver presses a mirrored glove against its surface, revealing a room inside.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "The Tin Fox triggers a hidden mechanism.",
      "visual_description": "The clockwork fox steps on a loose cobble, and a stone panel slides open to reveal a narrow passage.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "The Sleeping Tax Collector wakes briefly.",
      "visual_description": "The tax collector stirs, mutters about a toll, then immediately falls back asleep on his paper pillow.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 12,
      "caption": "The Oracle Lamp guides through a misty square.",
      "visual_description": "The lamp's flame cuts through thick fog in a plaza filled with flapping old royal banners and overturned carts.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Mara spots armored patrols on a parapet.",
      "visual_description": "From a shadowed archway, Mara watches figures in plate armor walk along a high wall, their lanterns bobbing.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "The group hides behind a shattered fountain.",
      "visual_description": "Crouched behind a dry fountain carved with old crests, the rescuers press close as footsteps echo nearby.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The Oracle Lamp reveals a hidden key.",
      "visual_description": "The lamp's glow illuminates a small iron key wedged between cobblestones, unnoticed by the patrols.",
      "characters": ["oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The Glass Diver unlocks the final door.",
      "visual_description": "The diver inserts the key into a rusted lock set into a stone wall, the mechanism clicking open.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 17,
      "caption": "The escape across the bridge begins.",
      "visual_description": "The group runs onto a long stone bridge spanning a dry moat, with old royal banners hanging from its pillars.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "The bridge collapses behind them.",
      "visual_description": "Stones tumble into the moat as the last person clears the bridge; the city's gates shut forever, leaving only dust and silence.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

